def func(lists, k):
    # Use a dictionary to count occurrences of each number
    count = {}
    for lst in lists:
        for num in lst:
            if num in count:
                count[num] += 1
            else:
                count[num] = 1

    # Use a max heap to find the k most frequent numbers
    max_heap = []
    for num, freq in count.items():
        heapq.heappush(max_heap, (-freq, num))
        if len(max_heap) > k:
            heapq.heappop(max_heap)

    # Extract the k most frequent numbers from the heap
