def largest_palindrome(arr, n):
    # Sort the array in descending order
    arr.sort(reverse=True)

    # Iterate through the sorted array
    for i in range(n):
        # Check if the current element is a palindrome
        if arr[i] == arr[i][::-1]:
            # Return the largest palindrome found
            return arr[i]

