def gcd(x, y):
    # Initialize gcd to the minimum of x and y
    gcd = min(x, y)
    # Loop through possible divisors from 1 to the minimum of x and y
    for i in range(1, gcd + 1):
        # If i is a divisor of both x and y, update gcd
        if x % i == 0 and y % i == 0:
            gcd = i
    return gcd

